lines = ["; nocat.farm setup - the setup's own words. Made by tools/installer/make-messages.py - edit that, not this file.", "", "[CustomMessages]"]
for key, per in M.items():
    assert len(per) == len(LANGS), key
    for lang, text in zip(LANGS, per):
        lines.append(f"{lang}.{key}={text}")
    lines.append("")
out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "messages.iss")
io.open(out, "w", encoding="utf-8-sig", newline="\r\n").write("\n".join(lines))
print("ok", len(M), "messages")
